package com.icewright.generated.api;

import com.icewright.generated.api.dto.AdminOverviewResponse;
import com.icewright.generated.api.dto.ConsoleSessionRow;
import com.icewright.generated.api.dto.SessionDetailResponse;
import com.icewright.generated.config.Settings;
import com.icewright.generated.domain.ApisRegistry;
